function makeCourier(){const w=backdoorWorld;const visual=window.NULLVISUALS?.agent?.(1);const root=visual?visual.root:new THREE.Group();w.courier={root,visual};if(visual){visual.gun.visible=false;visual.flash.visible=false;}root.position.copy(w.courierStart);w.root.add(root);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:labelTexture('SABLE','#acffed','ROGUE PROGRAM'),depthTest:true}));sprite.position.set(0,2.75,0);sprite.scale.set(1.8,.9,1);root.add(sprite);w.courier.label=sprite;}
