function courierPath(){const m=backdoorMission,w=backdoorWorld,from=w.courier.root.position;const room=w.rooms[m.room],bounds=room.bounds;const start=[Math.round(from.x),Math.round(from.z)],goal=[Math.round(player.x),Math.round(player.z)];const tag=(x,z)=>x+','+z,queue=[start],seen=new Map([[tag(...start),null]]);let end=null;for(let i=0;i<queue.length&&i<3500;i++){const [x,z]=queue[i];if(Math.hypot(x-goal[0],z-goal[1])<1.5){end=[x,z];break;}for(const [dx,dz] of [[0,1],[0,-1],[1,0],[-1,0]]){const nx=x+dx,nz=z+dz,key=tag(nx,nz);if(nx<bounds.minX||nx>bounds.maxX||nz<bounds.minZ||nz>bounds.maxZ||seen.has(key)||circleBlocked(nx,nz,.32,0))continue;seen.set(key,[x,z]);queue.push([nx,nz]);}}const path=[];while(end){path.push(v3(end[0],0,end[1]));end=seen.get(tag(...end));}path.reverse();m.path=path.slice(1);}
function updateCourier(dt){const m=backdoorMission,w=backdoorWorld,c=w.courier,from=c.root.position;let moving=false;if(m.recruited&&from.distanceTo(player)>2){m.pathClock-=dt;const direct=player.clone().sub(from);direct.y=0;const length=direct.length();let target;if(!colliders.some(b=>intersectBox(from.clone().add(v3(0,.7,0)),direct.clone().normalize(),{...b,w:b.w+.36,d:b.d+.36},length-.1)!==false)){target=player;}else{if(m.pathClock<=0){courierPath();m.pathClock=.6;}while(m.path.length&&m.path[0].distanceTo(from)<.45)m.path.shift();target=m.path[0];}if(target){const delta=target.clone().sub(from);delta.y=0;const len=delta.length();if(len>.05){delta.multiplyScalar(Math.min(len,dt*6.6)/len);const before=from.clone();moveBody(from,delta.x,delta.z,.32,0);moving=from.distanceToSquared(before)>.000001;if(moving)c.root.rotation.y=Math.atan2(delta.x,delta.z);}}}if(c.visual){const a=c.visual;if(a.actions.walk)a.actions.walk.weight=moving?1:0;if(a.actions.idle)a.actions.idle.weight=moving?0:1;a.mixer.update(dt);a.model.updateMatrixWorld(true);if(a.bones.Bip01_Head&&a.glasses){a.glasses.position.copy(a.root.worldToLocal(a.bones.Bip01_Head.getWorldPosition(v3()))).add(v3(0,.08,.155));}a.gun.visible=a.flash.visible=false;}c.label.visible=m.room==='office'&&!m.recruited||m.recruited;}
function updateBackdoors(dt){const m=backdoorMission,w=backdoorWorld;if(state!=='playing')return;m.transition=Math.max(0,m.transition-dt*2.2);m.cooldown=Math.max(0,m.cooldown-dt);const scanWanted=keys.has('KeyF')||touch.scan;if(!scanWanted)m.scanLatched=false;m.scan=scanWanted&&!m.scanLatched&&focus>1;if(m.scan){focus=Math.max(0,focus-dt*8);if(focus<=1)m.scanLatched=true;}if(!['escape','complete'].includes(m.phase)){m.rewriteTime-=dt;if(m.rewriteTime<=0){m.rewriteTime=24;m.revision=(m.revision+1)%6;m.transition=.55;tone(90,.4,.06,'triangle',45);if(m.room==='hub')toast('THE DOORS HAVE CHANGED. Hold F to decode them again.',4);}}
updateCourier(dt);const held=keys.has('KeyE')||touch.hack;if(!held)m.release=false;const target=activeBackdoorTarget();let action=null;
if(target.room===m.room&&Math.hypot(player.x-target.position.x,player.z-target.position.z)<2.7&&player.y<1.5)action={id:target.kind,label:target.label,target,duration:target.kind==='uplink'?2:1.2};
if(!action&&m.cooldown<=0)for(const door of [...w.portals,...w.returnPortals])if(door.room===m.room&&Math.hypot(player.x-door.position.x,player.z-door.position.z)<2.6&&player.y<1.5){const name=door.room==='hub'?(m.scan?portalDestination(door).toUpperCase():'BLACK DOOR '+door.id):'BACKDOOR NETWORK';action={id:door.id,label:'ENTER '+name,door,duration:.45};break;}
$('prompt').hidden=!action;$('hack').hidden=!action;if(!action){m.progress=0;m.interaction='';return;}const waiting=m.recruited&&w.courier.root.position.distanceTo(player)>4.8;$('prompt').innerHTML=waiting?'WAIT FOR SABLE · '+Math.ceil(w.courier.root.position.distanceTo(player))+' M':'<kbd>E</kbd> HOLD TO '+action.label;$('hack').querySelector('span').textContent=action.label;if(m.interaction!==action.id){m.interaction=action.id;m.progress=0;}if(held&&!m.release&&!waiting)m.progress=Math.min(1,m.progress+dt/action.duration);else m.progress=Math.max(0,m.progress-dt*.4);$('hack').querySelector('i').style.width=m.progress*100+'%';if(m.progress<1)return;m.progress=0;m.release=true;
if(action.door){teleportBackdoor(action.door);return;}if(action.target.kind==='sable'){m.recruited=true;m.phase='key';score+=700;health=clamp(health+25,0,100);focus=100;toast('SABLE: Find the maintenance key. I will follow you through the doors.',6);}else if(action.target.kind==='key'){m.keyTaken=true;m.phase='uplink';score+=900;focus=100;toast('ROUTE KEY RECOVERED. Bring Sable to the ROOFTOP uplink.',5);}else if(action.target.kind==='uplink'){m.phase='escape';m.transition=1;score+=1100;health=clamp(health+30,0,100);focus=100;toast('ROUTES STABILIZED. Enter ARCHIVE with Sable and find EXIT.',6);}else if(action.target.kind==='exit'&&m.recruited&&m.keyTaken&&m.phase==='escape'){m.phase='complete';finish(true);}tone(550,.35,.12,'sine',1100);
}

