const legs=[];for(const s of [-1,1]){const leg=new THREE.Group();leg.position.set(s*.18,.99,0);group.add(leg);box(.25,.72,.27,coat,0,-.35,0,leg);box(.27,.15,.43,boot,0,-.78,.06,leg);legs.push(leg);}
const arms=[];for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.43,1.7,0);group.add(arm);box(.21,.58,.22,coat,0,-.27,0,arm);box(.19,.15,.18,skin,0,-.61,0,arm);arms.push(arm);}
const pistol=box(.1,.11,.36,glasses,0,-.61,.14,arms[1]);const glow=new THREE.Mesh(new THREE.SphereGeometry(.04,8,6),new THREE.MeshBasicMaterial({color:0xff554a}));glow.position.set(.025,2.055,.227);group.add(glow);
